import json
from datetime import datetime, timedelta

def check_heartbeats(lines, now, max_age_minutes=10):
    last_seen = {}
    errors = 0
    for line in lines:
        try:
            event = json.loads(line)
            source = event["source"]
            ts = datetime.fromisoformat(event["event_time"].replace("Z", "+00:00"))
            if ts.tzinfo is None:
                raise ValueError("event_time must be timezone-aware")
            if source not in last_seen or ts > last_seen[source]:
                last_seen[source] = ts
        except (json.JSONDecodeError, KeyError, ValueError):
            errors += 1

    cutoff = now - timedelta(minutes=max_age_minutes)
    missing = sorted(source for source, ts in last_seen.items() if ts < cutoff)
    return {"missing": missing, "parse_errors": errors}

from collections import defaultdict, deque
from datetime import datetime, timedelta

def detect_burst_then_success(events):
    recent = defaultdict(deque)
    alerts = []

    for event in events:
        ts = datetime.fromisoformat(event["timestamp"].replace("Z", "+00:00"))
        key = (event["account"], event["source_ip"])
        q = recent[key]

        if event["result"] == "failure":
            q.append(ts)
            cutoff = ts - timedelta(minutes=10)
            while q and q[0] < cutoff:
                q.popleft()
        elif event["result"] == "success":
            cutoff = ts - timedelta(minutes=2)
            if sum(1 for t in q if t >= cutoff) >= 5:
                alerts.append({
                    "account": event["account"],
                    "source_ip": event["source_ip"],
                    "timestamp": event["timestamp"],
                    "reason": "five_or_more_recent_failures_followed_by_success"
                })
    return alerts

def normalize_windows(event):
    return {
        "timestamp": event["TimeCreated"],
        "host": event["Computer"],
        "user": event.get("SubjectUserName"),
        "parent_process": event.get("ParentImage"),
        "process": event.get("NewProcessName"),
        "source_name": "windows_security",
        "raw": event,
    }

def normalize_linux(event):
    return {
        "timestamp": event["timestamp"],
        "host": event["host"],
        "user": event.get("uid"),
        "parent_process": event.get("ppid"),
        "process": event.get("comm") or event.get("exe"),
        "source_name": "linux_audit",
        "raw": event,
    }

