from datetime import timedelta

def correlate_dns_alerts(dns_events, alerts):
    answers = {}
    for d in dns_events:
        key = (d["client"], d["answer"])
        answers.setdefault(key, []).append(d)

    results = []
    for a in alerts:
        for d in answers.get((a["src_ip"], a["dest_ip"]), []):
            delta = a["timestamp"] - d["timestamp"]
            if timedelta(0) <= delta <= timedelta(minutes=5):
                results.append({
                    "client": a["src_ip"],
                    "destination": a["dest_ip"],
                    "query": d["query"],
                    "dns_time": d["timestamp"],
                    "alert_time": a["timestamp"],
                    "signature": a["signature"]
                })
    return results

def hunt_service_accounts(events, expected_hosts):
    findings = []
    for event in events:
        account = event["account"]
        if not account.startswith("svc_"):
            continue
        allowed = set(expected_hosts.get(account, ()))
        if event["host"] not in allowed:
            findings.append({
                "type": "unexpected_service_account_host",
                "account": account,
                "host": event["host"],
                "target_service": event.get("target_service"),
                "timestamp": event["timestamp"],
                "evidence": event
            })
    return findings

