#!/usr/bin/env python3
import argparse
import json
from collections import defaultdict, deque
from datetime import datetime, timedelta, timezone
from pathlib import Path

def parse_ts(value):
    ts = datetime.fromisoformat(value.replace("Z", "+00:00"))
    if ts.tzinfo is None:
        raise ValueError("timestamp must include timezone")
    return ts.astimezone(timezone.utc)

def load_events(path):
    events = []
    errors = []
    for lineno, line in enumerate(Path(path).read_text().splitlines(), start=1):
        if not line.strip():
            continue
        try:
            event = json.loads(line)
            event["_ts"] = parse_ts(event["timestamp"])
            events.append(event)
        except (json.JSONDecodeError, KeyError, ValueError) as exc:
            errors.append({"line": lineno, "error": str(exc)})
    events.sort(key=lambda e: e["_ts"])
    return events, errors

def detect_auth_burst(events, min_failures=5, failure_window_minutes=10, success_window_minutes=2):
    recent = defaultdict(deque)
    findings = []
    for event in events:
        if event.get("event_type") not in {"authentication", "auth"}:
            continue
        key = (event.get("user"), event.get("source_ip"))
        ts = event["_ts"]
        q = recent[key]
        if event.get("result") == "failure":
            q.append(ts)
            cutoff = ts - timedelta(minutes=failure_window_minutes)
            while q and q[0] < cutoff:
                q.popleft()
        elif event.get("result") == "success":
            if q and (ts - q[-1]) <= timedelta(minutes=success_window_minutes) and len(q) >= min_failures:
                findings.append({
                    "type": "auth_burst_then_success",
                    "severity": "high",
                    "confidence": "medium",
                    "timestamp": event["timestamp"],
                    "user": event.get("user"),
                    "source_ip": event.get("source_ip"),
                    "reason": f"{min_failures}+ failures within the rolling window followed by a success",
                    "evidence": event
                })
                q.clear()
    return findings

def detect_unmanaged_privileged_logins(events):
    findings = []
    for event in events:
        if event.get("event_type") != "authentication":
            continue
        if event.get("result") != "success":
            continue
        if not event.get("privileged"):
            continue
        if event.get("managed_device") is False:
            findings.append({
                "type": "privileged_login_from_unmanaged_device",
                "severity": "high",
                "confidence": "high",
                "timestamp": event["timestamp"],
                "user": event.get("user"),
                "source_ip": event.get("source_ip"),
                "reason": "successful privileged authentication from unmanaged device",
                "evidence": event
            })
    return findings

def build_health_report(events, parse_errors):
    sources = sorted({e.get("source") for e in events if e.get("source")})
    counts = defaultdict(int)
    for event in events:
        counts[event.get("source", "unknown")] += 1
    return {
        "event_count": len(events),
        "parse_error_count": len(parse_errors),
        "sources": [{"source": s, "event_count": counts[s]} for s in sources],
        "status": "warning" if parse_errors else "healthy"
    }

def main():
    parser = argparse.ArgumentParser(description="Educational security monitoring pipeline")
    parser.add_argument("input")
    parser.add_argument("--out", default="findings.json")
    args = parser.parse_args()

    events, parse_errors = load_events(args.input)
    findings = detect_auth_burst(events) + detect_unmanaged_privileged_logins(events)
    report = {
        "findings": findings,
        "health": build_health_report(events, parse_errors),
        "parse_errors": parse_errors
    }
    Path(args.out).write_text(json.dumps(report, indent=2, default=str) + "\n")
    print(json.dumps({"findings": len(findings), "health": report["health"]["status"]}, indent=2))

if __name__ == "__main__":
    main()

