import json
import subprocess
import sys

SAMPLE = '''{"timestamp":"2026-09-07T10:00:00Z","event_type":"authentication","user":"alice","source_ip":"192.0.2.10","result":"failure","source":"idp"}
{"timestamp":"2026-09-07T10:01:00Z","event_type":"authentication","user":"alice","source_ip":"192.0.2.10","result":"failure","source":"idp"}
{"timestamp":"2026-09-07T10:02:00Z","event_type":"authentication","user":"alice","source_ip":"192.0.2.10","result":"failure","source":"idp"}
{"timestamp":"2026-09-07T10:03:00Z","event_type":"authentication","user":"alice","source_ip":"192.0.2.10","result":"failure","source":"idp"}
{"timestamp":"2026-09-07T10:04:00Z","event_type":"authentication","user":"alice","source_ip":"192.0.2.10","result":"failure","source":"idp"}
{"timestamp":"2026-09-07T10:05:00Z","event_type":"authentication","user":"alice","source_ip":"192.0.2.10","result":"success","source":"idp","privileged":false,"managed_device":true}
{"timestamp":"2026-09-07T10:06:00Z","event_type":"authentication","user":"bob","source_ip":"192.0.2.20","result":"success","source":"idp","privileged":true,"managed_device":false}
'''

def test_pipeline_detects_two_conditions(tmp_path):
    inp = tmp_path / "events.ndjson"
    out = tmp_path / "findings.json"
    inp.write_text(SAMPLE)
    subprocess.run([sys.executable, "monitor.py", str(inp), "--out", str(out)], check=True)
    result = json.loads(out.read_text())
    types = {f["type"] for f in result["findings"]}
    assert "auth_burst_then_success" in types
    assert "privileged_login_from_unmanaged_device" in types
    assert result["health"]["status"] == "healthy"

def test_bad_line_is_reported(tmp_path):
    inp = tmp_path / "events.ndjson"
    out = tmp_path / "findings.json"
    inp.write_text(SAMPLE + "not-json\n")
    subprocess.run([sys.executable, "monitor.py", str(inp), "--out", str(out)], check=True)
    result = json.loads(out.read_text())
    assert result["health"]["status"] == "warning"
    assert result["health"]["parse_error_count"] == 1
